add_filter( 'woocommerce_product_get_shipping_class_id', 'perfectpixel_default_shipping_class', 10, 2 );
add_filter( 'woocommerce_product_variation_get_shipping_class_id', 'perfectpixel_default_shipping_class', 10, 2 );

function perfectpixel_default_shipping_class( $class_id, $product ) {
	$default = (int) '{{default_shipping_class_id}}';
	if ( $class_id || ! $default ) {
		return $class_id;
	}
	// A variation without its own class inherits the parent's, if the parent has one.
	if ( $product && $product->get_parent_id() ) {
		$parent = wc_get_product( $product->get_parent_id() );
		if ( $parent && $parent->get_shipping_class_id( 'edit' ) ) {
			return $parent->get_shipping_class_id( 'edit' );
		}
	}
	return $default;
}
